import { useEffect, useState } from "react";
import API from "../api";
import EventCard from "../components/EventCard";

function Home() {
  const [events, setEvents] = useState([]);

  useEffect(() => {
    API.get("/events").then(res => setEvents(res.data.events));
  }, []);

  return (
    <div>
      <h2>All Events</h2>
      {events.map(e => <EventCard key={e._id} event={e} />)}
    </div>
  );
}

export default Home;
